/* From Uiverse.io by aymenthedeveloper  - Tags: icon, animation, button, toggle, light&dark, toggle switch */
.__UIV_SCOPE__ .toggle-btn {
  --bg: #e8e8e8;
  --fg: #212121;
  background-color: var(--bg);
  border-radius: 10px;
  --dimensions: 50px;
  width: var(--dimensions);
  height: var(--dimensions);
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0;
  padding: 0;
  cursor: pointer;
}

.__UIV_SCOPE__ .toggle-btn .main-circle {
  --dimensions: 20px;
  width: var(--dimensions);
  height: var(--dimensions);
  background-color: var(--fg);
  border-radius: 50%;
  position: absolute;
  transition: transform 0.4s ease 0.2s;
}

.__UIV_SCOPE__ .toggle-btn .main-circle::after {
  content: "";
  background-color: var(--bg);
  border-radius: 50%;
  --dimensions: 15px;
  width: var(--dimensions);
  height: var(--dimensions);
  position: absolute;
  top: 1px;
  right: -1px;
  transform-origin: right top;
  transform: scale(0);
  transition: transform 0.4s ease 0.2s;
}

.__UIV_SCOPE__ .toggle-btn .sun-rays {
  display: grid;
  place-items: center;
  transition: transform 0.4s ease 0.2s;
}

.__UIV_SCOPE__ .toggle-btn .sun-rays,
.__UIV_SCOPE__ .toggle-btn .sun-rays::after,
.__UIV_SCOPE__ .toggle-btn .sun-rays::before {
  --width: 3px;
  --height: 6px;
  width: var(--width);
  height: var(--height);
  background-color: var(--fg);
  position: absolute;
  box-shadow: 0 16px 0 var(--fg), 0 -16px 0 var(--fg);
}

.__UIV_SCOPE__ .toggle-btn .sun-rays::after {
  content: "";
  transform: rotate(120deg);
}

.__UIV_SCOPE__ .toggle-btn .sun-rays::before {
  content: "";
  transform: rotate(240deg);
}

.__UIV_SCOPE__ .toggle-btn:focus .main-circle {
  transform: scale(1.2);
}

.__UIV_SCOPE__ .toggle-btn:focus .main-circle::after {
  transform: scale(1);
}

.__UIV_SCOPE__ .toggle-btn:focus .sun-rays {
  transition: transform 0.4s;
  transform: scale(0);
}

@media (prefers-color-scheme: dark) {
  .__UIV_SCOPE__ .toggle-btn {
    --bg: #212121;
    --fg: #e8e8e8;
  }
}
